<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$pdo=db();$done=['abandoned'=>0,'expired_memberships'=>0];try{$q=$pdo->query("SELECT c.*,COALESCE(s.abandoned_cart_hours,12) hours FROM commerce_carts_v1230 c LEFT JOIN commerce_settings_v1230 s ON s.tenant_id=c.tenant_id WHERE c.status='active' AND c.reminder_sent_at IS NULL AND COALESCE(c.updated_at,c.created_at)<=DATE_SUB(NOW(),INTERVAL COALESCE(s.abandoned_cart_hours,12) HOUR) AND EXISTS(SELECT 1 FROM commerce_cart_items_v1230 i WHERE i.cart_id=c.id) ORDER BY c.id LIMIT 100");foreach($q->fetchAll()?:[] as $c){$pdo->prepare("INSERT INTO commerce_notifications_v1230(tenant_id,user_id,visitor_key,title,body,target_url,event_key,created_at) VALUES(?,?,?,'Your OneCart is waiting','You still have local products in your ShahkotPK cart.','/cart-v1230.php','abandoned_cart',NOW())")->execute([(int)$c['tenant_id'],$c['user_id']?:null,(string)$c['visitor_key']]);$pdo->prepare('UPDATE commerce_carts_v1230 SET reminder_sent_at=NOW() WHERE id=?')->execute([(int)$c['id']]);$done['abandoned']++;}}catch(Throwable $e){}
try{$q=$pdo->prepare("UPDATE membership_subscriptions_v1230 SET status='expired',updated_at=NOW() WHERE status='active' AND ends_at IS NOT NULL AND ends_at<NOW()");$q->execute();$done['expired_memberships']=$q->rowCount();}catch(Throwable $e){}
echo json_encode(['ok'=>true,'processed'=>$done,'time'=>date('c')],JSON_UNESCAPED_SLASHES).PHP_EOL;
